import json
def parse_note(raw):
    if len(raw.encode("utf-8")) > 200: raise ValueError("too large")
    data=json.loads(raw)
    if not isinstance(data,dict) or set(data)!={"body"}: raise ValueError("shape")
    if not isinstance(data["body"],str): raise ValueError("type")
    return data["body"]
print(parse_note('{"body":"demo"}'))
# expected: demo; no network or file reference is interpreted.
